                base = max(base, 67.0)
        return float(min(budget, base))

    if tight_supply:
        bid = 28.0
        if urgent_opponents >= 1:
            bid = 18.0
        if david_prev_bid is not None:
            if david_prev_bid < 60:
                bid = max(bid, min(42.0, david_prev_bid + 3.0))
            elif david_prev_bid >= 90:
                bid = min(bid, 16.0)
        return float(min(budget, bid))

