def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no alive opponents, conserve budget.
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from surviving opponents only.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how competitive the market was.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        second_prev = 0.0
        avg_prev = 0.0

    # Supply pressure: with higher supply, we can bid less to still win; with lower supply, bid more.
    # Normalize supply into [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        norm = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        norm = 0.5
    norm = max(0.0, min(1.0, norm))

    # Base target: slightly below the highest observed survivor bid to avoid overpaying.
    # Alex/David around 83-89 survived; match slightly under that.
    target = DAILY_SALARY * (0.85 - 0.15 * norm)

    # If they were bidding very high yesterday, raise a bit to avoid being outbid today.
    if highest_prev_bid > 0.0:
        # If highest_prev_bid was near/above 0.9*DAILY_SALARY, we must be closer.
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            target = max(target, DAILY_SALARY * 0.9 - 10.0 * (1.0 - norm))
        elif highest_prev_bid >= DAILY_SALARY * 0.8:
            target = max(target, DAILY_SALARY * 0.82 - 6.0 * (1.0 - norm))

    # If my hp is low or I have missed water days, bid more aggressively.
    if hp <= 2.0 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.95)
    elif hp <= 4.0 or no_water_days >= 1:
        target = max(target, DAILY_SALARY * 0.88)

    # Keep target below the highest observed bid to try to win cheaper.
    if highest_prev_bid > 0.0:
        target = min(target, highest_prev_bid - 1.0)

    # Ensure non-negative and within budget.
    bid = max(0.0, min(budget, target))

    # If budget is extremely low, still bid something only if hp is critical.
    if bid <= 0.0 and (hp <= 2.0 or no_water_days >= 2):
        bid = min(budget, DAILY_SALARY * 0.5)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return 10.0

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 85.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], avg_opp_bid * 1.2)
    elif supply < WATER_REQ + 2:
        bid = min(my_status['budget'], avg_opp_bid * 1.05)
    else:
        bid = min(my_status['budget'], avg_opp_bid * 0.9)

    return float(max(1.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_competitors = len(alive_opponents) + 1

    available_slots = int(current_supply // WATER_REQ)

    base_bid = DAILY_SALARY * 0.7

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if num_competitors > available_slots:
            if highest_prev_bid >= DAILY_SALARY * 0.9:
                base_bid = max(base_bid, highest_prev_bid + 5.0)
            elif highest_prev_bid >= DAILY_SALARY * 0.6:
                base_bid = max(base_bid, highest_prev_bid + 2.0)
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.75)
        else:
            if highest_prev_bid >= DAILY_SALARY * 0.8:
                base_bid = max(base_bid, DAILY_SALARY * 0.6)
            elif highest_prev_bid >= DAILY_SALARY * 0.4:
                base_bid = max(base_bid, highest_prev_bid * 0.9)
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.35)

    if my_hp <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 1.3)
    elif my_hp <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 1.05)

    if my_no_water_days > 0:
        base_bid = max(base_bid, DAILY_SALARY * 1.1)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 1.2)
    elif remaining_days <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.95)

    final_bid = max(1.0, min(my_budget, base_bid))

    return final_bid
